<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { Plus,KeyRound,Copy,ShieldCheck,Info } from 'lucide-vue-next'
import { ElMessage,ElMessageBox } from 'element-plus'
import StatusTag from '../components/StatusTag.vue'
import { getVirtualKeys,createVirtualKey,revokeVirtualKey } from '../api/virtualKeys'
import { errorMessage } from '../api/http'
import type { VirtualKey } from '../types'
const apiOrigin=window.location.origin
const keys=ref<VirtualKey[]>([]),loading=ref(true),error=ref(''),dialog=ref(false),name=ref(''),rpm=ref(60),creating=ref(false),newKey=ref('')
async function load(){loading.value=true;error.value='';try{keys.value=await getVirtualKeys()}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function create(){if(!name.value.trim()){ElMessage.warning('请输入密钥名称');return}creating.value=true;try{const result=await createVirtualKey(name.value.trim(),rpm.value);newKey.value=result.key;name.value='';await load();ElMessage.success('密钥已创建')}catch(e){ElMessage.error(errorMessage(e))}finally{creating.value=false}}
async function revoke(key:VirtualKey){try{await ElMessageBox.confirm(`撤销“${key.name}”后将无法继续使用。`,'撤销密钥',{confirmButtonText:'确认撤销',cancelButtonText:'取消',type:'warning'});await revokeVirtualKey(key.id);await load();ElMessage.success('密钥已撤销')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorMessage(e))}}
async function copy(){try{await navigator.clipboard.writeText(newKey.value);ElMessage.success('密钥已复制')}catch{ElMessage.error('复制失败，请手动保存')}}
function openCreate(){newKey.value='';name.value='';dialog.value=true}
const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN')
onMounted(load)
</script>
<template><section class="page-heading"><div><h1 class="page-title">虚拟密钥</h1><p class="page-subtitle">为应用分配独立凭据，统一管理模型访问。</p></div><button class="btn btn-primary" @click="openCreate"><Plus :size="16"/>创建密钥</button></section><div class="note-banner"><ShieldCheck :size="18"/><span>虚拟密钥仅用于模型调用，与控制台管理员凭据独立。密钥明文仅在创建时显示一次。</span></div><div v-if="error" class="error-state" role="alert">{{error}}<button class="text-link" @click="load">重试</button></div><el-skeleton v-if="loading" :rows="7" animated/><section v-else class="panel"><div class="panel-head"><div class="panel-title-with-count"><h2 class="panel-title">应用密钥</h2><span class="count-badge">{{keys.length}}</span></div><span class="muted">{{keys.filter(k=>k.status==='active').length}} 个使用中</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>名称</th><th>密钥前缀</th><th>状态</th><th class="align-right">RPM 上限</th><th class="align-right">请求数</th><th>创建时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="key in keys" :key="key.id"><td><span class="key-name"><KeyRound :size="16"/>{{key.name}}</span></td><td class="mono muted">{{key.prefix}}••••••</td><td><StatusTag :status="key.status"/></td><td class="mono align-right">{{key.rpm_limit}}</td><td class="mono align-right">{{key.total_requests.toLocaleString()}}</td><td class="muted">{{date(key.created_at)}}</td><td class="align-right"><button class="btn btn-quiet danger-text" :disabled="key.status==='revoked'" @click="revoke(key)">{{key.status==='revoked'?'已撤销':'撤销'}}</button></td></tr><tr v-if="!keys.length"><td colspan="7" class="empty-state">还没有虚拟密钥，创建一枚来接入你的应用。</td></tr></tbody></table></div></section><div class="code-example panel"><div class="panel-head"><h2 class="panel-title">在应用中调用</h2><span class="plain-tag">OpenAI 兼容</span></div><pre><code>curl {{apiOrigin}}/v1/chat/completions \
  -H "Authorization: Bearer &lt;你的虚拟密钥&gt;" \
  -H "Content-Type: application/json" \
  -d '{"model":"gpt-4o-mini","messages":[{"role":"user","content":"Hello"}]}'</code></pre></div><el-dialog v-model="dialog" title="创建虚拟密钥" width="480px" :close-on-click-modal="false"><template v-if="newKey"><div class="note-banner"><Info :size="18"/><span>请立即保存，关闭窗口后将无法再次查看明文。</span></div><div class="new-key-display"><code>{{newKey}}</code><button class="icon-btn" aria-label="复制新密钥" @click="copy"><Copy :size="17"/></button></div></template><form v-else @submit.prevent="create"><label class="form-label" for="key-name">名称</label><el-input id="key-name" v-model="name" maxlength="60" placeholder="例如：开发环境应用"/><label class="form-label space-top">每分钟请求上限</label><el-input-number v-model="rpm" :min="1" :max="1000" aria-label="每分钟请求上限"/><p class="field-note">Demo 使用单进程限流，不代表生产级共享额度。</p></form><template #footer><el-button @click="dialog=false">{{newKey?'已保存，关闭':'取消'}}</el-button><el-button v-if="!newKey" type="primary" :loading="creating" @click="create">创建密钥</el-button></template></el-dialog></template>
